import { useEffect, useId, useRef, useState } from 'react';
import { SAMPLE_STATUSES, SAMPLE_TRANSITIONS, updateSample } from '../../lib/vendor-sampling';
import { toJakartaInput, fromJakartaInput } from '../../lib/vendor-followup-helpers';
export default function SampleStatusModal({ sample, options, profileId, onClose, onSaved }) {
  const ref = useRef(null), pending = useRef(false), prefix = useId();
  const [form, setForm] = useState({ status: SAMPLE_TRANSITIONS[sample.status]?.[0] || sample.status, assigned_at: sample.assigned_at ? toJakartaInput(sample.assigned_at) : toJakartaInput(), target_date: sample.target_date || '', received_at: sample.received_at ? toJakartaInput(sample.received_at) : toJakartaInput(), internal_pic_id: sample.internal_pic_id || profileId || '', revision_note: '' });
  const [busy, setBusy] = useState(false), [error, setError] = useState('');
  useEffect(() => { const d = ref.current; d.showModal(); return () => d.close(); }, []);
  const change = (e) => setForm((s) => ({ ...s, [e.target.name]: e.target.value }));
  const submit = async (e) => { e.preventDefault(); if (pending.current) return; pending.current = true; setBusy(true); setError(''); try { await updateSample(sample, { ...form, assigned_at: fromJakartaInput(form.assigned_at), target_date: form.target_date || null, received_at: ['SAMPEL_DITERIMA', 'SEDANG_QC'].includes(form.status) || sample.received_at ? fromJakartaInput(form.received_at) : null }); onSaved(); } catch (err) { setError(err.message); } finally { pending.current = false; setBusy(false); } };
  return <dialog ref={ref} aria-labelledby={prefix + 'title'} onCancel={(e) => { e.preventDefault(); if (!busy) onClose(); }} className="m-auto w-[calc(100%-2rem)] max-w-lg max-h-[90vh] overflow-y-auto rounded-xl border border-white/10 bg-ink-900 text-white p-5 backdrop:bg-black/70"><form className="space-y-4" onSubmit={submit}><h2 id={prefix + 'title'} className="text-lg font-semibold">Perbarui Status Sampel</h2><p className="text-xs text-ink-400">{sample.sample_code} · Perubahan tersimpan pada riwayat.</p>
    <div><label className="label" htmlFor={prefix + 'status'}>Status berikutnya</label><select id={prefix + 'status'} className="input" name="status" value={form.status} onChange={change} disabled={busy}>{(SAMPLE_TRANSITIONS[sample.status] || []).map((s) => <option key={s} value={s}>{SAMPLE_STATUSES[s]}</option>)}</select></div>
    {['assigned_at', 'target_date', 'received_at'].map((n) => <div key={n}><label className="label" htmlFor={prefix + n}>{n === 'assigned_at' ? 'Tanggal penugasan (WIB)' : n === 'target_date' ? 'Target selesai' : 'Tanggal diterima (WIB)'}</label><input id={prefix + n} name={n} type={n === 'target_date' ? 'date' : 'datetime-local'} className="input" value={form[n]} onChange={change} disabled={busy} required={form.status !== 'DIBATALKAN' && n !== 'received_at'} /></div>)}
    <div><label className="label" htmlFor={prefix + 'pic'}>PIC HARMAS</label><select id={prefix + 'pic'} name="internal_pic_id" className="input" value={form.internal_pic_id} onChange={change} disabled={busy}><option value="">Pilih PIC…</option>{options.users.map((u) => <option key={u.id} value={u.id}>{u.full_name}</option>)}</select></div>
    <div><label className="label" htmlFor={prefix + 'reason'}>Catatan revisi / alasan pembatalan</label><textarea id={prefix + 'reason'} name="revision_note" className="input" value={form.revision_note} onChange={change} disabled={busy} required={sample.status === 'PERLU_REVISI' || form.status === 'DIBATALKAN'} minLength={5} /></div>
    {error && <p role="alert" className="text-sm text-danger-400">{error}</p>}<div className="flex justify-end gap-2"><button type="button" className="btn-secondary" disabled={busy} onClick={onClose}>Batal</button><button className="btn-primary" disabled={busy}>{busy ? 'Menyimpan…' : 'Simpan Status'}</button></div>
  </form></dialog>;
}
